const places={prologue:['다리 위에 남은 이름','끊어진 밧줄 아래로 계곡의 바람이 지나갔다.'],trail:['솔바람에 묻힌 발걸음','전령의 흔적은 소나무 그늘 너머로 사라졌다.'],waterway:['멈춰 버린 물길','낡은 취수로에는 물소리만 남았다.'],pass:['안개 속 마지막 약속','고갯길의 안개가 돌아갈 길을 덮었다.'],alley:['골목에 멎은 발소리','청운문 아래 골목은 다시 조용해졌다.'],'canal-sentry':['물 위에 지워진 경고','푸른 부적이 수면 위를 천천히 맴돌았다.'],sealkeeper:['전하지 못한 인장','닫힌 수문 너머에서 종소리가 멀어졌다.']};
export function deathScene(s){const b=s.battle||{},place=places[b.zone]||places.prologue,cause=b.log?.slice(-5).some(e=>/화상|발화|중독|출혈/.test(e.text))?'status':b.effects?.some(e=>e.actor==='enemy'&&e.magic)?'spell':'weapon',suffix={status:'남아 있던 결',spell:'끊어진 숨',weapon:'끝내 닿지 못한 손'}[cause];return {id:(b.zone||'prologue')+'-'+cause,title:place[0]+' · '+suffix,text:place[1]+' '+({status:'몸에 남은 상태 효과를 견뎌 낼 힘이 없었다.',spell:'완성된 술식은 마지막 방어를 넘어왔다.',weapon:'마지막 공방 뒤에는 다시 자세를 잡을 여유가 없었다.'}[cause])};}
